  const orderedEntries = SAMPLE.filter((entry) => entry.scope !== 'auto');
  const orderedKeys = orderedEntries.map((entry) => entry.key);
  const extraKeys = [...merged.keys()].filter((key) => !orderedKeys.includes(key));

  const lines = [
    `# Generated by \`npm run env -- ${tier}\` — do not edit directly.`,
    `# Edit .env.shared or .env.${tier} instead, then re-run the switch.`,
    '',
    `ENVIRONMENT_NAME=${tier}`,
    `DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}`,
    '',
  ];
  for (const { section, entries } of groupBySection(orderedEntries)) {
    const groupLines = entries
      .filter((entry) => merged.has(entry.key))
      .map((entry) => `${entry.key}=${merged.get(entry.key)}`);
    if (!groupLines.length) continue;
    lines.push(`# ── ${section} ──`, ...groupLines, '');
  }
  if (extraKeys.length) {
    lines.push('# ── Other ──', ...extraKeys.map((key) => `${key}=${merged.get(key)}`), '');
  }
  fs.writeFileSync(path.join(ROOT, '.env'), lines.join('\n').replace(/\n+$/, '\n'));

  console.log(`Switched to "${tier}" (DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}).`);
  const blanks = [...merged.entries()].filter(([, value]) => !value).map(([key]) => key);
  if (blanks.length) {
    console.log(`\nHeads up — these values are still blank in .env.shared / .env.${tier}:`);
    blanks.forEach((key) => console.log(`  - ${key}`));
    console.log('\nRun `npm run env -- validate` for a fuller check.');

