#!/usr/bin/env node
/**
 * Contentful setup diagnostic — answers "is Contentful fully set up?" with evidence.
 *
 * Every check is designed to be able to FAIL. Run it against a deliberately broken
 * credential to confirm that before trusting a green run.
 *
 *   node checkContentful.mjs                       # working tree, all tiers
 *   node checkContentful.mjs --rev origin/develop   # read code facts from a git rev
 *   node checkContentful.mjs --tier dev             # single tier
 *   node checkContentful.mjs --probe-write          # opt-in: real write to a scratch type
 *
 * Exits non-zero if any check FAILs. Never prints credential values.
 */
import { execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ARGV = process.argv.slice(2);
const flag = (n, d = null) => {
  const i = ARGV.indexOf(n);
  return i === -1 ? d : ARGV[i + 1] ?? true;
};
const REV = flag('--rev');
const ONLY_TIER = flag('--tier');
const PROBE_WRITE = ARGV.includes('--probe-write');
const ROOT = execSync('git rev-parse --show-toplevel').toString().trim();
const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];

const results = [];
const record = (id, label, status, detail) => {
  results.push({ id, label, status, detail });
  const icon = { PASS: '\x1b[32m✓\x1b[0m', FAIL: '\x1b[31m✗\x1b[0m', WARN: '\x1b[33m!\x1b[0m', SKIP: '\x1b[90m-\x1b[0m' }[status];
  console.log(`  ${icon} ${label}`);
