    pe.CONTENTFUL_DELIVERY_TOKEN, 'cdn.contentful.com');
  if (!r.ok) {
    record('E1', 'uiCopy keys resolve from CMS', 'FAIL', `HTTP ${r.status} reading uiCopy entries`);
  } else {
    const liveKeys = new Set((r.body.items ?? []).map((i) => i.fields?.key).filter(Boolean));
    const missing = [...callKeys].filter((k) => !liveKeys.has(k)).sort();
    const unused = [...liveKeys].filter((k) => !callKeys.has(k)).sort();
    record('E1', `every t() key has a published uiCopy entry (${primary})`, missing.length ? 'FAIL' : 'PASS',
      missing.length
        ? `${missing.length} key(s) SILENTLY falling back to hardcoded English — invisible in the UI:\n${missing.join('\n')}`
        : `all ${callKeys.size} call-site keys resolve from Contentful`);
    record('E2', 'no orphaned uiCopy entries', unused.length ? 'WARN' : 'PASS',
      unused.length ? `published but never read by code: ${unused.join(', ')}` : 'none');
  }
}

// ══════════════════════ F. generated-definitions freshness ══════════════════
head('F. Codegen freshness');
try {
  execSync('npm run generate:contentful:check', { cwd: ROOT, stdio: 'pipe' });
  record('F1', 'contentful definitions.ts up to date', 'PASS');
} catch (err) {
  const out = `${err.stdout ?? ''}${err.stderr ?? ''}`.trim().split('\n').slice(-3).join('\n');
  record('F1', 'contentful definitions.ts up to date', /Missing script/.test(out) ? 'SKIP' : 'FAIL', out);
}

// ═════════════════════════════════ summary ══════════════════════════════════
const n = (s) => results.filter((r) => r.status === s).length;
console.log(`\n${'─'.repeat(70)}`);
console.log(`\x1b[1mContentful setup: ${n('PASS')} pass, ${n('FAIL')} fail, ${n('WARN')} warn, ${n('SKIP')} skip\x1b[0m`);
if (cmaOwner) console.log(`CMA token owner: ${cmaOwner}`);
const fails = results.filter((r) => r.status === 'FAIL');
if (fails.length) {
  console.log(`\n\x1b[31mNOT fully set up.\x1b[0m Blocking:`);
  fails.forEach((f) => console.log(`  ✗ [${f.id}] ${f.label}`));
} else {
  console.log(`\n\x1b[32mFully set up\x1b[0m (for the surfaces this script covers).`);
}
process.exit(fails.length ? 1 : 0);
